-- catchap_ai.ai_training_dataset 뷰
--
-- 원본: catchap_dev_db 의 SHOW CREATE VIEW (김민서님 수급, 2026-07-31)
-- 새 스키마용으로 정규화한 것:
--   ALGORITHM=UNDEFINED  제거 (기본값)
--   DEFINER=catchap_dba@%  제거 — 내 계정으로 만든다
--   SQL SECURITY DEFINER -> INVOKER — 뷰가 소유자 권한으로 도는 것을 막는다.
--                                     읽는 쪽 권한으로 평가되는 편이 안전하다
--   `catchap_dev_db`. 한정자 제거 — 같은 스키마 안에서 해석되게
--
-- ⚠️ 아직 적용 못 함: catchap_ai 계정에 CREATE VIEW 권한이 없다.
--    GRANT CREATE VIEW, SHOW VIEW ON catchap_ai.* TO 'catchap_ai'@'10.0.1.%';
--    권한이 오면 이 파일을 그대로 실행하면 된다.

CREATE SQL SECURITY INVOKER VIEW `ai_training_dataset` AS select `a`.`id` AS `attempt_id`,`a`.`challenge_id` AS `challenge_id`,`a`.`session_id` AS `session_id`,`a`.`participant_id` AS `participant_id`,`a`.`label` AS `training_label`,`a`.`label_source` AS `label_source`,`a`.`bot_type` AS `bot_type`,`a`.`quality_status` AS `quality_status`,`a`.`is_correct` AS `is_correct`,`a`.`verification_result` AS `verification_result`,`a`.`device_type` AS `device_type`,`a`.`pointer_type` AS `pointer_type`,`a`.`browser_name` AS `browser_name`,`a`.`operating_system` AS `operating_system`,`a`.`viewport_width` AS `viewport_width`,`a`.`viewport_height` AS `viewport_height`,`a`.`screen_width` AS `screen_width`,`a`.`screen_height` AS `screen_height`,`a`.`device_pixel_ratio` AS `device_pixel_ratio`,`a`.`expected_target_count` AS `expected_target_count`,`a`.`selected_object_count` AS `selected_object_count`,`f`.`feature_version` AS `feature_version`,`f`.`reaction_time_ms` AS `reaction_time_ms`,`f`.`total_duration_ms` AS `total_duration_ms`,`f`.`active_duration_ms` AS `active_duration_ms`,`f`.`idle_duration_ms` AS `idle_duration_ms`,`f`.`pointer_event_count` AS `pointer_event_count`,`f`.`pointer_move_count` AS `pointer_move_count`,`f`.`pointer_down_count` AS `pointer_down_count`,`f`.`pointer_up_count` AS `pointer_up_count`,`f`.`drag_count` AS `drag_count`,`f`.`drop_count` AS `drop_count`,`f`.`wrong_click_count` AS `wrong_click_count`,`f`.`wrong_drag_count` AS `wrong_drag_count`,`f`.`correction_count` AS `correction_count`,`f`.`object_revisit_count` AS `object_revisit_count`,`f`.`hesitation_count` AS `hesitation_count`,`f`.`pause_count` AS `pause_count`,`f`.`total_path_length` AS `total_path_length`,`f`.`drag_path_length` AS `drag_path_length`,`f`.`straight_line_distance` AS `straight_line_distance`,`f`.`straightness_ratio` AS `straightness_ratio`,`f`.`average_speed` AS `average_speed`,`f`.`max_speed` AS `max_speed`,`f`.`speed_stddev` AS `speed_stddev`,`f`.`average_acceleration` AS `average_acceleration`,`f`.`max_acceleration` AS `max_acceleration`,`f`.`average_jerk` AS `average_jerk`,`f`.`average_curvature` AS `average_curvature`,`f`.`direction_change_count` AS `direction_change_count`,`f`.`movement_entropy` AS `movement_entropy`,`sf`.`replay_similarity_score` AS `replay_similarity_score`,`sf`.`exact_sequence_match` AS `exact_sequence_match`,`sf`.`nonce_reuse_detected` AS `nonce_reuse_detected`,`sf`.`challenge_reuse_detected` AS `challenge_reuse_detected`,`sf`.`session_mismatch_detected` AS `session_mismatch_detected`,`sf`.`timestamp_anomaly_detected` AS `timestamp_anomaly_detected`,`sf`.`event_order_anomaly_detected` AS `event_order_anomaly_detected`,`sf`.`webdriver_detected` AS `webdriver_detected`,`sf`.`headless_browser_detected` AS `headless_browser_detected`,`sf`.`automation_property_detected` AS `automation_property_detected`,`sf`.`duplicate_fingerprint_count` AS `duplicate_fingerprint_count`,`sf`.`recent_session_attempt_count` AS `recent_session_attempt_count`,`sf`.`recent_challenge_attempt_count` AS `recent_challenge_attempt_count`,`sf`.`recent_failure_count` AS `recent_failure_count`,`sf`.`session_frequency_score` AS `session_frequency_score`,`sf`.`challenge_frequency_score` AS `challenge_frequency_score`,`a`.`started_at` AS `started_at`,`a`.`completed_at` AS `completed_at`,`a`.`created_at` AS `attempt_created_at`,`f`.`extracted_at` AS `extracted_at` from ((`ai_behavior_attempts` `a` join `ai_attempt_features` `f` on(((`f`.`attempt_id` = `a`.`id`) and (`f`.`extraction_status` = 'completed')))) left join `ai_security_features` `sf` on((`sf`.`attempt_id` = `a`.`id`))) where ((`a`.`quality_status` = 'valid') and (`a`.`label` in ('human','bot')) and (`a`.`label_source` is not null) and (trim(`a`.`label_source`) <> ''));
